const c=$input.first().json.config;
if(!c.API_BASE_URL||!/^https?:\/\//.test(c.API_BASE_URL)||!c.CORREO_MARISA||!c.CORREO_REMITENTE)throw new Error('Falta configuración del informe');
const hoy=$now.setZone('Europe/Madrid');
const mes=hoy.minus({months:1});return [{json:{config:c,desde:mes.startOf('month').toISODate(),hasta:mes.endOf('month').toISODate(),medido:hoy.toISO()}}];

const cent=v=>{if(!/^(0|[1-9]\d*)(\.\d{1,2})?$/.test(String(v)))throw new Error('Importe inválido');const [a,b='']=String(v).split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n))throw new Error('Importe fuera de rango');return n;};
const add=(a,b)=>{const n=a+b;if(!Number.isSafeInteger(n))throw new Error('Total fuera de rango');return n;};
const euros=n=>(n/100).toFixed(2)+' EUR';
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
const medios=['efectivo','tarjeta','bizum','transferencia'];
const list=(r,requireCount=false)=>{if(r.statusCode!==200||!Array.isArray(r.body))throw new Error('Respuesta API incompleta');if(requireCount&&Number(r.headers?.['x-total-count'])!==r.body.length)throw new Error('Lista API incompleta');return r.body;};
const totals=(rows,desde,hasta)=>{const by={efectivo:0,tarjeta:0,bizum:0};const ids=new Set();let total=0;for(const r of rows){if(!Number.isSafeInteger(r.id)||r.id<1||ids.has(r.id)||!date(r.fecha)||r.fecha<desde||r.fecha>hasta||!medios.includes(r.forma_pago))throw new Error('Movimiento API inválido');ids.add(r.id);const n=cent(r.importe);if(n<=0)throw new Error('Movimiento sin importe positivo');by[r.forma_pago]=add(by[r.forma_pago]||0,n);total=add(total,n);}return {total,by};};

const apartados=list($('Consultar apartados').first().json,true),ids=new Set();
for(const a of apartados){if(!Number.isSafeInteger(a.id)||a.id<1||ids.has(a.id)||!date(a.fecha)||!['activo','liquidado','vencido'].includes(a.estado))throw new Error('Apartado API inválido');ids.add(a.id);cent(a.pendiente);}
const liquidados=apartados.filter(a=>a.estado==='liquidado');
return liquidados.length?liquidados.map(a=>({json:{id:a.id}})):[{json:{sin_liquidados:true}}];

const cent=v=>{if(!/^(0|[1-9]\d*)(\.\d{1,2})?$/.test(String(v)))throw new Error('Importe inválido');const [a,b='']=String(v).split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n))throw new Error('Importe fuera de rango');return n;};
const add=(a,b)=>{const n=a+b;if(!Number.isSafeInteger(n))throw new Error('Total fuera de rango');return n;};
const euros=n=>(n/100).toFixed(2)+' EUR';
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
const medios=['efectivo','tarjeta','bizum','transferencia'];
const list=(r,requireCount=false)=>{if(r.statusCode!==200||!Array.isArray(r.body))throw new Error('Respuesta API incompleta');if(requireCount&&Number(r.headers?.['x-total-count'])!==r.body.length)throw new Error('Lista API incompleta');return r.body;};
const totals=(rows,desde,hasta)=>{const by={efectivo:0,tarjeta:0,bizum:0};const ids=new Set();let total=0;for(const r of rows){if(!Number.isSafeInteger(r.id)||r.id<1||ids.has(r.id)||!date(r.fecha)||r.fecha<desde||r.fecha>hasta||!medios.includes(r.forma_pago))throw new Error('Movimiento API inválido');ids.add(r.id);const n=cent(r.importe);if(n<=0)throw new Error('Movimiento sin importe positivo');by[r.forma_pago]=add(by[r.forma_pago]||0,n);total=add(total,n);}return {total,by};};

const p=$('Fijar período').first().json;
const v=totals(list($('Consultar ventas').first().json,true),p.desde,p.hasta),a=totals(list($('Consultar abonos').first().json),p.desde,p.hasta);
const apartados=list($('Consultar apartados').first().json,true),vales=list($('Consultar vales').first().json);
const paid=apartados.filter(a=>a.estado==='liquidado');
const detalles=$input.all().filter(i=>!i.json.sin_liquidados).map(i=>{if(i.json.statusCode!==200||!i.json.body||Array.isArray(i.json.body))throw new Error('Detalle incompleto');return i.json.body;});
if(detalles.length!==paid.length||new Set(detalles.map(d=>d.id)).size!==paid.length)throw new Error('Faltan detalles de liquidación');
const dentro=f=>{if(!date(f))throw new Error('Fecha API inválida');return f>=p.desde&&f<=p.hasta;};
let liquidados=0;
for(const d of detalles){if(!paid.some(a=>a.id===d.id)||d.estado!=='liquidado'||!Array.isArray(d.abonos)||!d.abonos.length)throw new Error('Detalle liquidado inválido');for(const b of d.abonos)if(b.apartado_id!==d.id||!date(b.fecha))throw new Error('Abono de detalle inválido');const ultima=d.abonos.map(b=>b.fecha).sort().at(-1);if(dentro(ultima))liquidados++;}
const valeIds=new Set(),apartadoIds=new Set();for(const vale of vales){if(!Number.isSafeInteger(vale.id)||valeIds.has(vale.id)||apartadoIds.has(vale.apartado_id)||!apartados.some(a=>a.id===vale.apartado_id&&a.estado==='vencido'))throw new Error('Vale API inválido');valeIds.add(vale.id);apartadoIds.add(vale.apartado_id);}
const pendiente=apartados.filter(a=>a.estado==='activo').reduce((n,a)=>add(n,cent(a.pendiente)),0);
const nuevos=apartados.filter(a=>dentro(a.fecha)).length,vencidos=vales.filter(v=>dentro(v.fecha)).length,total=add(v.total,a.total);
const documento={periodo_desde:p.desde,periodo_hasta:p.hasta,ventas_centimos:v.total,abonos_centimos:a.total,total_centimos:total,pendiente_actual_centimos:pendiente,pendiente_medido_en:p.medido,nuevos,liquidados,vencidos,destinatario:p.config.CORREO_MARISA,remitente:p.config.CORREO_REMITENTE,asunto:`Paso Firme · Informe ${p.desde.slice(0,7)}`,texto:`Informe ${p.desde} a ${p.hasta}\nConcepto | Importe\nVentas directas | ${euros(v.total)}\nAbonos | ${euros(a.total)}\nTotal recaudado | ${euros(total)}\nPendiente actual (medido ${p.medido}, no histórico) | ${euros(pendiente)}\nNuevos: ${nuevos}\nLiquidados: ${liquidados}\nVencidos: ${vencidos}${total===0?'\nSin cobros en el período.':''}`};
return [{json:{clave:`informe:${p.desde.slice(0,7)}:${p.config.CORREO_MARISA}`,tipo:'informe_mensual',documento}}];
